entries[201404] = { ["name"] = "Dämonenschrecken", ["text"] = "30 Meter Reichweite\nCa. 1.5 Procs pro Minute\nGewährt eine Chance, bei einem Nahkampfangriff 'Dämonenschrecken' auszulösen. Erhöht 15 Sek. lang Eure Stärke um 99 und jeglichen Schaden gegen Dämonen um 10%. Wenn Ihr dabei einem Gegner einen Todesstoß versetzt, wird die Dauer um 8 Sek. erhöht (maximal bis zur ursprünglichen Dauer)." }
