entries[201496] = { ["name"] = "Frittierte Mooskieme", ["text"] = "Wirken in 2 sek.\nReagenzien:\nMooskiemenbarsch (5), Moschushirschbutter (5)\nBereitet eine frittierte Mooskieme zu.\nQuest:\nEs hat sich ausgekrächzt\nZone:\nVal'sharah\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Tempo.\n40" }
entries[201497] = { ["name"] = "Eingelegter Sturmrochen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSturmrochen (5), Grobes Meersalz (3)\nBereitet einen eingelegten Sturmrochen zu.\nQuest:\nSchwere Bürde\nZone:\nSturmheim\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Meisterschaft.\n40" }
entries[201498] = { ["name"] = "Faronaarsprudel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nWildvogelei (5), Flusszwiebel (2), Königliche Olive (3)\nBereitet Faronaarsprudel zu.\nQuest:\nDer Magister der Mixologie\nZone:\nAzsuna\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 8 Vielseitigkeit.\n40" }
entries[201499] = { ["name"] = "Würziger Rippchenbraten", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGroße Wildrippchen (5), Dalapeñoschote (5)\nBereitet einen würzigen Rippchenbraten zu.\nQuest:\nZahltag\nZone:\nSturmheim\nGegenstand:\nSechszünders Vorratskiste\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet eine Chance, beim Angreifen eine Salve Pfefferatemfeuerbälle abzufeuern, die jeweils 105 Feuerschaden verursachen. Dieser Effekt hält 1 Stunde lang an.\n40" }
entries[201500] = { ["name"] = "Grillrippchen à la Ley", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeyblut (5), Große Wildrippchen (5), Dalapeñoschote (5)\nBereitet Grillrippchen à la Ley zu.\nBeute von:\nMyonix\nZone:\nSuramar\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 11 kritischen Trefferwert.\n40" }
entries[201501] = { ["name"] = "Meeresschnitzel Suramar", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenschuppenkoi (5), Magere Haxe (5), Grobes Meersalz (2), Königliche Olive (4)\nBereitet ein Meeresschnitzel Suramar zu.\nBeute von:\nSuramar\nGegenstand:\nRezept: Meer, Rezept: Schnitzel\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 11 Tempo.\n40" }
entries[201502] = { ["name"] = "Barrakuda à la Mrglgagh", ["text"] = "Wirken in 2 sek.\nReagenzien:\nLeyblut (5), Schwarzer Barrakuda (5), Moschushirschbutter (4), Flusszwiebel\nBereitet einen Barrakuda à la Mrglgagh zu.\nQuest:\nMurlocs: Die nächste Generation\nZone:\nDer Hochberg\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 11 Meisterschaft.\n40\n\"Das ist mrglantisch!\"" }
entries[201503] = { ["name"] = "Sturmrochen mit Koiaroma", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRunenschuppenkoi (5), Sturmrochen (5), Grobes Meersalz (2), Moschushirschbutter (2)\nBereitet einen Sturmrochen mit Koiaroma zu.\nVerkäufer:\nMarkus Hjolbruk\nZone:\nSuramar\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 28846 Gesundheit und 14423 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 11 Vielseitigkeit.\n40" }
